const KEY='ramadhanpro-v1';
/* global __APP_VERSION__ */
const APP_VERSION=typeof __APP_VERSION__==='string'?__APP_VERSION__:'dev';
document.querySelectorAll('[data-app-version]').forEach(el=>{el.textContent=APP_VERSION});
    const NAV=[['home',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg>`,'Beranda'],['calendar',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="17" rx="3"/><path d="M8 2v4M16 2v4M3 10h18"/></svg>`,'Kalender'],['daily',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><path d="M8.5 12.5l2.5 2.5 4.5-5"/></svg>`,'Mutabaah'],['plan',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>`,'Rencana'],['report',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/></svg>`,'Rapor'],['settings',`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1"/><circle cx="15" cy="6" r="2"/><circle cx="9" cy="12" r="2"/><circle cx="17" cy="18" r="2"/></svg>`,'Akun']];
    const PRAYERS=['Subuh','Dzuhur','Ashar','Maghrib','Isya'];
    const HABITS=['Shalat Subuh berjamaah','Tilawah Al-Qur’an','Sedekah harian'];
    const PREP_CHECKS=['Menghubungi orang tua dan keluarga','Menyelesaikan kewajiban finansial','Menyiapkan perlengkapan ibadah','Menetapkan waktu istirahat yang cukup'];
    const RAMADAN_TASKS=['Rawatib','Dhuha','Tarawih','Witir','Zikir pagi dan petang','Doa berbuka','Sedekah hari ini'];
    const defaults={settings:{ramadanStart:'2027-02-08',qadhaOwed:0,qadhaDone:0,qadhaDeadline:'2027-02-07',quranGoal:30,sadaqahGoal:0,zakatFitrah:45000,nisab:85000000,tarawihTarget:30,theme:'muslim',mode:'light',displayName:'Sahabat',city:'',latitude:null,longitude:null,prayerMethod:'kemenag',madhab:'shafi',imsakOffset:10,prayerAdjust:{fajr:0,sunrise:0,dhuhr:0,asr:0,maghrib:0,isha:0},hijriOffset:0,reminders:false,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone},days:{},fasting:{preRamadan:[],syawal:[]},prepDone:[],duas:[],family:[],kajian:[],infaq:[],card:{recipient:'Keluarga dan sahabat',sender:'',message:'Selamat Idulfitri. Mohon maaf lahir dan batin. Semoga Allah menerima amal ibadah kita.'},zakatFitrahPaid:false,habits:{},iktikaf:false,schemaVersion:SCHEMA_VERSION,createdAt:Date.now(),lastBackupAt:0,backupSnoozeUntil:0,updatedAt:0};
    function themeV2(next){try{if(localStorage.getItem('ramadhanpro-theme-v2')!=='1')next.settings.mode='light'}catch{}return next}
    function markThemeV2(){try{localStorage.setItem('ramadhanpro-theme-v2','1')}catch{}}
    function mergeSnapshot(saved){return themeV2({...structuredClone(defaults),...saved,settings:{...defaults.settings,...saved?.settings,prayerAdjust:{...defaults.settings.prayerAdjust,...saved?.settings?.prayerAdjust}},days:saved?.days||{},fasting:{...defaults.fasting,...saved?.fasting},kajian:saved?.kajian||[],infaq:saved?.infaq||[],card:{...defaults.card,...saved?.card},schemaVersion:SCHEMA_VERSION})}
    let legacySnapshotPresent=false;
    function load(){try{const raw=localStorage.getItem(KEY);const saved=JSON.parse(raw||'null');legacySnapshotPresent=saved!==null&&typeof saved==='object';return mergeSnapshot(saved||{})}catch{return structuredClone(defaults)}}
    let db=load(),view='home',selectedDate=keyOf(new Date()),toastTimer;
    let persistTimer,localChanges=false,storageInfo={persisted:null,usage:null,quota:null};
    function persistNow(){let localFailed=false;try{localStorage.setItem(KEY,JSON.stringify(db))}catch{localFailed=true}clearTimeout(persistTimer);const snapshot=structuredClone(db);persistTimer=setTimeout(()=>saveSnapshot(KEY,snapshot).catch(()=>{if(localFailed)notify('Penyimpanan perangkat penuh. Unduh cadangan data.')}),150)}
    function save(){localChanges=true;db.updatedAt=Date.now();persistNow()}
    function refreshStorage(){return storageStatus().then(info=>{storageInfo=info;if(view==='settings')render()})}
    function ensurePersistence(){return requestPersistence().then(refreshStorage)}
    /* IndexedDB = sumber utama; localStorage = cermin untuk tampilan pertama dan cadangan.
       Jika keduanya ada, yang bercap waktu terbaru dipakai (lihat pickNewer di src/backup.js). */
    readSnapshot(KEY).then(record=>{
      const picked=pickNewer(db,legacySnapshotPresent,record?.value);
      if(!localChanges){if(picked.source==='remote')db=mergeSnapshot(picked.value);persistNow()}
      markThemeV2();render();
    }).catch(()=>{if(!localChanges)persistNow();markThemeV2();render()}).finally(()=>{profileIsReady()?ensurePersistence():refreshStorage()});
    function keyOf(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
    function dayRecord(k=selectedDate){return db.days[k] ||= {prayers:Array(5).fill(false),tasks:{},pages:0,sadaqah:0,water:[false,false,false,false,false,false,false,false],fast:false,mood:0,note:'',dua:''}}
    function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
    function dateDiff(a,b){const x=new Date(`${a}T12:00:00`),y=new Date(`${b}T12:00:00`);return Math.round((y-x)/86400000)}
    function phaseInfo(){const n=keyOf(new Date()),delta=dateDiff(db.settings.ramadanStart,n);if(delta<0)return{key:'prep',label:'Persiapan • Sya’ban',title:'Siapkan ruang untuk Ramadhan.',detail:`${-delta} hari menuju perkiraan awal Ramadhan`,day:0};if(delta<10)return{key:'ramadan',label:'Ramadhan • Rahmat',title:'Bangun kebiasaan yang bertahan.',detail:`Hari ${delta+1} Ramadhan`,day:delta+1};if(delta<20)return{key:'ramadan',label:'Ramadhan • Maghfirah',title:'Jaga ritme, beri ruang untuk pulih.',detail:`Hari ${delta+1} Ramadhan`,day:delta+1};if(delta<30)return{key:'last',label:'Ramadhan • 10 malam terakhir',title:'Lapangkan waktu untuk ibadah malam.',detail:`Hari ${delta+1} Ramadhan`,day:delta+1};if(delta<33)return{key:'eid',label:'Syawal • Hari Raya',title:'Rayakan kemenangan dengan syukur.',detail:`Hari ${delta-29} Syawal`,day:delta-29};return{key:'post',label:'Syawal • Istiqamah',title:'Rawat kebiasaan baikmu.',detail:'Perjalanan berlanjut setelah Ramadhan',day:0}}
    function todayScore(r=dayRecord(keyOf(new Date()))){const total=r.prayers.length+RAMADAN_TASKS.length+1,done=r.prayers.filter(Boolean).length+RAMADAN_TASKS.filter((_,i)=>r.tasks[i]).length+(r.pages>0?1:0);return Math.round(done/total*100)}
    function streak(){let date=new Date(),count=0;if(!db.days[keyOf(date)]||todayScore(db.days[keyOf(date)])===0)date.setDate(date.getDate()-1);while(db.days[keyOf(date)]&&todayScore(db.days[keyOf(date)])>0){count++;date.setDate(date.getDate()-1)}return count}
    function fmtDMY(x){const d=x instanceof Date?x:typeof x==='number'?new Date(x):dateFromKey(x);return `${d.getDate()}/${d.getMonth()+1}/${d.getFullYear()}`}
    function initialsOf(name){const parts=String(name||'').trim().split(/\s+/).filter(Boolean);if(!parts.length)return 'RP';const a=parts[0][0]||'',b=parts.length>1?parts[parts.length-1][0]:(parts[0][1]||'');return (a+b).toUpperCase()}
    function greetingNow(){const h=new Date().getHours();return h<11?['Selamat Pagi','🌤️']:h<15?['Selamat Siang','☀️']:h<18?['Selamat Sore','⛅']:['Selamat Malam','🌙']}
    function lastDays(n){return Array.from({length:n},(_,i)=>db.days[keyPlus(keyOf(new Date()),i-(n-1))]||null)}
    function sparkSVG(values){const w=64,h=24,max=Math.max(...values,1),pts=values.map((v,i)=>`${(i/(values.length-1)*w).toFixed(1)},${(h-3-(v/max)*(h-6)).toFixed(1)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
    const SVG_IC=d=>`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
    function statCards(){const week=lastDays(7),score=week.map(r=>r?todayScore(r):0),prayers=week.map(r=>r?r.prayers.filter(Boolean).length:0),pages=week.map(r=>r?Number(r.pages)||0:0);let run=0;const streakSeries=score.map(v=>(run=v>0?run+1:0));const today=score[6],yesterday=score[5],diff=today-yesterday,trendScore=diff>0?`↗ +${diff}% dari kemarin`:diff<0?`↘ ${diff}% dari kemarin`:'→ Sama seperti kemarin',open=5-prayers[6],weekPages=pages.reduce((a,b)=>a+b,0);
      const cards=[['violet','Skor hari ini',`${today}%`,score,trendScore,'<circle cx="12" cy="12" r="9"/><path d="M8.5 12.5l2.5 2.5 4.5-5"/>'],['rose','Hari konsisten',String(streak()),streakSeries,streak()>0?'↗ Terus jaga ritmemu':'→ Mulai dari hari ini','<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M8 2v4M16 2v4M3 10h18M9 15l2 2 4-4"/>'],['sun','Shalat tercatat',`${prayers[6]}/5`,prayers,open>0?`→ ${open} lagi hari ini`:'↗ Lengkap hari ini','<path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a7 7 0 0 0 10.5 10.5z"/>'],['sky','Halaman Qur’an',String(pages[6]),pages,`↗ ${weekPages} hal. dalam 7 hari`,'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21.5zM4 19.5V5.5M8 7h7"/>']];
      return `<div class="stat-row" role="list">${cards.map(([tone,label,value,series,trend,icon])=>`<article class="stat" data-tone="${tone}" role="listitem"><div class="stat-top"><span class="stat-ico">${SVG_IC(icon)}</span>${sparkSVG(series)}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-trend">${trend}</div></article>`).join('')}</div>`}
    function heroArt(){return `<svg viewBox="0 0 330 230" role="img" aria-label="Ilustrasi kartu ibadah dengan bulan sabit dan grafik"><defs><linearGradient id="hg-card" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#eee9fb"/></linearGradient><linearGradient id="hg-bar1" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8b78e6"/><stop offset="1" stop-color="#6a56cb"/></linearGradient><linearGradient id="hg-bar2" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff9aa8"/><stop offset="1" stop-color="#e86a82"/></linearGradient><linearGradient id="hg-bar3" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffd978"/><stop offset="1" stop-color="#f0b43c"/></linearGradient><linearGradient id="hg-bar4" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8fb8ff"/><stop offset="1" stop-color="#5b8def"/></linearGradient><linearGradient id="hg-coin" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ffe08a"/><stop offset="1" stop-color="#eba92a"/></linearGradient></defs><ellipse cx="150" cy="212" rx="118" ry="9" fill="#8f7fd6" opacity=".28"/><rect x="26" y="52" width="224" height="146" rx="20" fill="url(#hg-card)" stroke="#ffffff" stroke-width="3"/><circle cx="46" cy="70" r="5" fill="#f26b6b"/><circle cx="62" cy="70" r="5" fill="#f5c04a"/><circle cx="78" cy="70" r="5" fill="#5ccf8b"/><rect x="40" y="88" width="196" height="96" rx="14" fill="#ebe5fb"/><path d="M92 128a22 22 0 1 0 24 29 17 17 0 0 1-24-29z" fill="#6a56cb"/><path d="M82 112l3 6 6.5.9-4.7 4.6 1.1 6.5-5.9-3.1-5.9 3.1 1.1-6.5-4.7-4.6 6.5-.9z" fill="#f5c04a" transform="translate(8 -6) scale(.8)"/><rect x="132" y="146" width="17" height="30" rx="6" fill="url(#hg-bar1)"/><rect x="154" y="132" width="17" height="44" rx="6" fill="url(#hg-bar2)"/><rect x="176" y="150" width="17" height="26" rx="6" fill="url(#hg-bar3)"/><rect x="198" y="120" width="17" height="56" rx="6" fill="url(#hg-bar4)"/><circle cx="262" cy="62" r="30" fill="#ffb34d"/><path d="M262 62V32a30 30 0 0 1 28 40z" fill="#8f7fe8"/><path d="M262 62l28 10a30 30 0 0 1-40 14z" fill="#ff8aa0"/><circle cx="262" cy="62" r="13" fill="#d7cef6"/><g><ellipse cx="270" cy="176" rx="28" ry="9" fill="url(#hg-coin)"/><rect x="242" y="167" width="56" height="9" fill="url(#hg-coin)"/><ellipse cx="270" cy="167" rx="28" ry="9" fill="#ffe9a6"/><ellipse cx="270" cy="156" rx="28" ry="9" fill="url(#hg-coin)"/><rect x="242" y="147" width="56" height="9" fill="url(#hg-coin)"/><ellipse cx="270" cy="147" rx="28" ry="9" fill="#ffe9a6"/></g><path d="M20 126c0-7 5-11 10-11 4 0 7 2 9 5 2-3 5-5 9-5 5 0 10 4 10 11 0 12-19 22-19 22s-19-10-19-22z" fill="#f26b82" transform="translate(-6 28) scale(.8)"/><g transform="translate(14 14)"><rect x="0" y="0" width="64" height="40" rx="16" fill="#ffffff"/><path d="M14 38l-6 12 18-12z" fill="#ffffff"/><circle cx="20" cy="20" r="4" fill="#c9c0ee"/><circle cx="32" cy="20" r="4" fill="#a99be8"/><circle cx="44" cy="20" r="4" fill="#7b68de"/></g></svg>`}
    function navHTML(){return NAV.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><i class="nav-icon" aria-hidden="true">${icon}</i><span>${label}</span></button>`).join('')}
    function mobileNavHTML(){return `<div class="nav-pill">${navHTML()}</div><button class="fab" data-view="daily" aria-label="Catat mutabaah hari ini" title="Catat mutabaah hari ini">${SVG_IC('<path d="M12 5v14M5 12h14"/>')}</button>`}
    function taskHTML(label,checked,action,value=''){return `<label class="task"><input type="checkbox" data-action="${action}" ${value!==''?`data-value="${value}"`:''} ${checked?'checked':''}><span>${esc(label)}</span></label>`}
    function dateFromKey(key){const [year,month,day]=key.split('-').map(Number);return new Date(year,month-1,day,12)}
    function prayerSchedule(key=keyOf(new Date())){const {latitude,longitude,prayerMethod,madhab,imsakOffset,prayerAdjust,timezone}=db.settings;if(latitude==null||longitude==null)return null;try{return calculatePrayerSchedule({latitude,longitude,date:dateFromKey(key),method:prayerMethod,madhab,imsakOffset,adjustments:prayerAdjust,timeZone:timezone||Intl.DateTimeFormat().resolvedOptions().timeZone})}catch{return null}}
    function scheduleCard(){const schedule=prayerSchedule();if(!schedule)return `<section class="panel span-7"><div class="panel-head"><h2>Jadwal shalat & imsak</h2><span class="pill">Hitung lokal</span></div><p class="muted small">Masukkan koordinat kota atau gunakan lokasi saat ini. Jadwal dihitung di perangkat dan tidak mengirim lokasi ke server.</p><button class="btn" data-view="settings">Atur lokasi & metode</button></section>`;const rows=Object.entries(schedule.times);return `<section class="panel span-7"><div class="panel-head"><h2>Jadwal shalat & imsak</h2><span class="pill">${esc(db.settings.city||'Lokasi tersimpan')}</span></div><div class="schedule-times">${rows.map(([name,time])=>`<div class="schedule-time"><span>${name}</span><strong>${esc(time)}</strong></div>`).join('')}</div><p class="schedule-meta">${esc(schedule.method)}${schedule.manual?' + koreksi manual':''} · ${esc(schedule.timezone)} · kiblat ${schedule.qiblaBearing}° dari utara. Cocokkan dengan jadwal masjid/otoritas setempat.</p><button class="link-btn" data-view="calendar">Lihat kalender Ramadhan →</button></section>`}
    const ADJUST_FIELDS=[['fajr','Subuh'],['sunrise','Terbit'],['dhuhr','Dzuhur'],['asr','Ashar'],['maghrib','Maghrib'],['isha','Isya']];
    function prayerSettings(){return `<section class="panel" id="prayer-settings"><div class="panel-head"><h2>Lokasi & metode jadwal</h2><span class="pill">Dihitung offline</span></div><p class="muted small">Jadwal dihitung di perangkat dengan pustaka Adhan. Lokasi tidak dikirim ke layanan luar. Hasil dapat berbeda dari penetapan resmi; cocokkan dengan masjid atau Kementerian Agama setempat.</p><label class="field" style="margin-bottom:12px"><span>Pilih kota (koordinat & zona waktu terisi otomatis)</span><select data-city-pick><option value="">Pilih kota…</option>${CITIES.map((c,i)=>`<option value="${i}">${esc(c[0])}</option>`).join('')}</select></label><div class="location-fields"><label class="field"><span>Lintang</span><input type="number" step="0.000001" min="-90" max="90" data-prayer-setting="latitude" value="${db.settings.latitude??''}" placeholder="Contoh: -6.2088"></label><label class="field"><span>Bujur</span><input type="number" step="0.000001" min="-180" max="180" data-prayer-setting="longitude" value="${db.settings.longitude??''}" placeholder="Contoh: 106.8456"></label><label class="field"><span>Nama lokasi</span><input type="text" data-prayer-setting="city" value="${esc(db.settings.city)}" maxlength="60" placeholder="Kota atau kabupaten"></label><label class="field"><span>Zona waktu</span><input type="text" data-prayer-setting="timezone" value="${esc(db.settings.timezone||'Asia/Jakarta')}" placeholder="Asia/Jakarta"></label></div><div class="schedule-method"><label class="field"><span>Metode perhitungan</span><select data-prayer-setting="prayerMethod">${Object.entries(CALCULATION_METHODS).map(([key,option])=>`<option value="${key}" ${db.settings.prayerMethod===key?'selected':''}>${esc(option.label)}</option>`).join('')}</select></label><label class="field"><span>Mazhab untuk Ashar</span><select data-prayer-setting="madhab"><option value="shafi" ${db.settings.madhab==='shafi'?'selected':''}>Syafi’i / Maliki / Hanbali</option><option value="hanafi" ${db.settings.madhab==='hanafi'?'selected':''}>Hanafi</option></select></label><label class="field"><span>Imsak sebelum Subuh (menit)</span><input type="number" min="0" max="60" data-prayer-setting="imsakOffset" value="${db.settings.imsakOffset??10}"></label></div>${db.settings.prayerMethod==='indonesia'?'<p class="muted small" style="margin:8px 0 0">Untuk Indonesia, metode “Kemenag RI” mengikuti kriteria resmi: Subuh 20°, Isya 18°, ihtiyath +2 menit.</p>':''}<details class="adjust"><summary>Koreksi manual per waktu (menit)</summary><p class="muted small">Ditambahkan di atas metode yang dipilih. Pakai bila jadwal masjid setempat berbeda beberapa menit (−30 sampai +30).</p><div class="location-fields">${ADJUST_FIELDS.map(([k,l])=>`<label class="field"><span>${l}</span><input type="number" min="-30" max="30" step="1" data-prayer-setting="adjust.${k}" value="${db.settings.prayerAdjust?.[k]??0}"></label>`).join('')}</div></details><div class="feature-actions"><button class="btn primary" data-action="locate-prayer">Gunakan lokasi perangkat</button><button class="btn" data-action="calculate-prayer">Hitung jadwal</button></div><div id="prayer-preview" class="schedule-meta">${prayerSchedule()?`${esc(prayerSchedule().method)}${prayerSchedule().manual?' + koreksi manual':''} · ${esc(prayerSchedule().timezone)} · kiblat ${prayerSchedule().qiblaBearing}° dari utara.`:'Masukkan lokasi untuk menghitung jadwal.'}</div></section>`}
    let calMonth=null;
    function calendar(){const today=keyOf(new Date());if(!calMonth)calMonth=selectedDate.slice(0,7);const [cy,cm]=calMonth.split('-').map(Number),first=new Date(cy,cm-1,1,12),daysIn=new Date(cy,cm,0).getDate(),offset=(first.getDay()+6)%7,rs=db.settings.ramadanStart,re=keyPlus(rs,29),weekdays=['Sen','Sel','Rab','Kam','Jum','Sab','Min'],pad=n=>String(n).padStart(2,'0'),selected=selectedDate,cells=Array(offset).fill('<span aria-hidden="true"></span>');
      for(let d=1;d<=daysIn;d++){const key=`${cy}-${pad(cm)}-${pad(d)}`,record=db.days[key],complete=!!(record&&(record.prayers.some(Boolean)||record.pages||record.note||Object.values(record.tasks||{}).some(Boolean))),inRam=key>=rs&&key<=re,n=inRam?dateDiff(rs,key)+1:0,hj=hijriParts(key,db.settings.hijriOffset);cells.push(`<button class="month-day ${key===selected?'selected':''} ${key===today?'today':''} ${inRam?'ramadan':''}" data-action="calendar-select" data-date="${key}" aria-label="${fmtDMY(key)}${inRam?`, Ramadhan hari ${n}`:''}${complete?', ada catatan':''}" aria-pressed="${key===selected}">${complete?'<i class="day-dot" aria-hidden="true"></i>':''}<span class="greg">${d}</span><span class="hijri">${inRam?`Hari ${n}`:(hj?hj.day:'')}</span></button>`)}
      const monthLabel=new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(first),schedule=prayerSchedule(selected),selRam=selected>=rs&&selected<=re,selDate=dateFromKey(selected),hijriSel=formatHijri(selected,db.settings.hijriOffset);
      return shellPage('Kalender',monthLabel,`<div class="grid"><section class="panel span-7"><div class="panel-head"><h2>Kalender ibadah</h2><div class="cal-nav"><button class="icon-btn small" data-action="calendar-month" data-delta="-1" aria-label="Bulan sebelumnya" title="Bulan sebelumnya">${SVG_IC('<path d="M15 5l-7 7 7 7"/>')}</button><button class="btn" data-action="calendar-today">Hari ini</button><button class="icon-btn small" data-action="calendar-month" data-delta="1" aria-label="Bulan berikutnya" title="Bulan berikutnya">${SVG_IC('<path d="M9 5l7 7-7 7"/>')}</button></div></div><div class="month-grid">${weekdays.map(day=>`<span class="month-weekday">${day}</span>`).join('')}${cells.join('')}</div><p class="muted small" style="margin:12px 0 0">Angka kecil di bawah tanggal adalah tanggal Hijriah (perkiraan). Hari berlatar ungu adalah 30 hari Ramadhan menurut awal Ramadhan yang kamu atur (${fmtDMY(rs)}); konfirmasi awal bulan kepada otoritas setempat.</p></section><section class="panel span-5" id="calendar-selected"><div class="panel-head"><h2>${selRam?`Hari ${dateDiff(rs,selected)+1} Ramadhan`:'Tanggal terpilih'}</h2><span class="pill">${new Intl.DateTimeFormat('id-ID',{weekday:'long'}).format(selDate)}, ${fmtDMY(selected)}</span></div>${hijriSel?`<p class="muted small" style="margin:-4px 0 12px">${esc(hijriSel)}</p>`:''}${schedule?`<div class="schedule-times">${Object.entries(schedule.times).map(([name,time])=>`<div class="schedule-time"><span>${name}</span><strong>${esc(time)}</strong></div>`).join('')}</div><p class="schedule-meta">${esc(schedule.method)}${schedule.manual?' + koreksi manual':''} · ${esc(schedule.timezone)}</p>`:'<p class="muted small">Atur lokasi dan metode perhitungan untuk melihat jadwal salat.</p><button class="btn" data-view="settings">Atur jadwal</button>'}<div class="calendar-actions" style="margin-top:14px"><button class="btn primary" data-action="calendar-open" data-date="${selected}">${selected===today?'Buka Mutabaah hari ini':'Buka Mutabaah tanggal ini'}</button><span class="muted small">${db.days[selected]?'Sudah ada catatan':'Belum ada catatan'}</span></div></section><section class="panel span-12"><div class="panel-head"><h2>Ringkasan target</h2><span class="pill">${db.settings.quranGoal} juz</span></div><p class="muted small">Pilih satu tanggal untuk membuka Mutabaah pada hari tersebut. Progres tersimpan privat di perangkatmu.</p></section></div>`)}
    function prayerSettingsPage(){return `${prayerSettings()}`}
    function pageHead(title,subtitle){return `<div class="page-head"><div><div class="eyebrow">${esc(title)}</div><h1>${esc(subtitle)}</h1></div></div>`}
    function topbarHTML(){const label=(NAV.find(n=>n[0]===view)||NAV[0])[2];return `<header class="topbar"><div class="top-id"><div class="top-title">${label}</div><div class="date-label">${hijriLabel()}${new Intl.DateTimeFormat('id-ID',{weekday:'long'}).format(new Date())}, ${fmtDMY(new Date())}</div></div><form class="top-search" data-search-form role="search"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="M20 20l-4-4"/></svg><input name="q" type="search" autocomplete="off" placeholder="Cari fitur, doa, zakat…" aria-label="Cari fitur"></form><div class="top-actions"><button class="icon-btn install-btn" data-action="install" aria-label="Pasang aplikasi" title="Pasang aplikasi"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 4v11M7 11l5 5 5-5M5 20h14"/></svg><span class="install-label">Pasang</span></button><button class="icon-btn" data-dialog="app-dialog" aria-label="Bantuan dan tentang aplikasi" title="Bantuan &amp; tentang"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M9.5 9.5a2.5 2.5 0 1 1 3.5 2.3c-.7.4-1 .9-1 1.7M12 17h.01"/></svg></button><button class="icon-btn" data-view="settings" aria-label="Pengaturan" title="Pengaturan"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="3.6"/><path d="M5 20c.8-3.7 3.5-5.6 7-5.6s6.2 1.9 7 5.6"/></svg></button></div></header>`}
    function shellPage(title,subtitle,body){const isHome=title.startsWith('Persiapan')||title.startsWith('Ramadhan')||title.startsWith('Syawal');return `${topbarHTML()}${isHome?'':pageHead(title,subtitle)}${title==='Pengaturan & privasi'?themeSettings()+prayerSettingsPage():''}${title==='Rencana fase'?planLinks():''}${body}${title==='Rencana fase'?planExtras():''}`}
    function inspirationBlock(){const copy=db.settings.theme==='muslimah'?['TEMANI HATI DENGAN IKHTIAR','Rawat niat, ilmu, dan amal yang kamu mampu.','Tak harus sempurna untuk terus bertumbuh.']:['NIAT · IKHTIAR · ISTIQAMAH','Teguhkan niat, jaga langkah kecil setiap hari.','Amal yang terpelihara tumbuh dari konsistensi.'];return `<section class="inspiration-panel"><div class="inspiration-mark" aria-hidden="true"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a7 7 0 0 0 10.5 10.5z"/></svg></div><div class="inspiration-copy"><div class="eyebrow">${copy[0]}</div><p>${copy[1]}</p><small>${copy[2]}</small></div></section>`}
    function themeSettings(){const theme=db.settings.theme==='muslimah'?'muslimah':'muslim',mode=db.settings.mode==='light'?'light':'dark';return `<section class="panel theme-settings"><div class="panel-head"><h2>Tema tampilan</h2><span class="pill">${theme==='muslim'?'Violet · lavender':'Orchid · rose'} · ${mode==='light'?'terang':'gelap'}</span></div><p class="muted small">Pilih suasana dan tingkat terang yang nyaman untuk perjalanan ibadahmu.</p><div class="theme-switch" role="group" aria-label="Pilih tema"><button data-theme-choice="muslim" aria-pressed="${theme==='muslim'}">☾　Muslim</button><button data-theme-choice="muslimah" aria-pressed="${theme==='muslimah'}">✿　Muslimah</button></div><div class="theme-switch" role="group" aria-label="Pilih mode terang atau gelap" style="margin-top:8px"><button data-mode-choice="light" aria-pressed="${mode==='light'}">☼　Terang</button><button data-mode-choice="dark" aria-pressed="${mode==='dark'}">◐　Gelap</button></div></section>`}
    function heroHTML(p,score,r,left){const [greet,emoji]=greetingNow(),who=(db.settings.displayName||'Sahabat').split(/\s+/)[0],open=5-r.prayers.filter(Boolean).length,n=nextEvent(),tag=n?`${esc(n.name)} · ${new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:db.settings.timezone||undefined}).format(n.at)}`:`Mutabaah ${score}%`,lead=left>0?`Ada <b>${left} hari</b> menuju awal Ramadhan pilihanmu`:`<b>${esc(p.detail)}</b>${p.day?` · Hari ${p.day}`:''}`,tail=open>0?`<b>${open} shalat</b> belum dicatat hari ini`:'semua <b>shalat</b> hari ini sudah tercatat';return `<section class="hero"><div class="hero-art">${heroArt()}<span class="hero-tag"><i aria-hidden="true"></i>${tag}</span></div><div class="hero-copy"><h2 class="hero-greet">${greet}, ${esc(who)}! ${emoji}</h2><p class="intro">${lead} dan ${tail}. Satu langkah kecil hari ini cukup berarti.</p><button class="btn primary" data-view="daily">${SVG_IC('<path d="M12 5v14M5 12h14"/>')}${score?'Lanjutkan mutabaah':'Mulai mutabaah hari ini'}</button></div></section>`}
    function home(){const p=phaseInfo(),score=todayScore(),r=dayRecord(keyOf(new Date())),left=dateDiff(keyOf(new Date()),db.settings.ramadanStart),quote=quoteBank[Math.floor(Date.now()/86400000)%quoteBank.length];document.documentElement.dataset.phase=p.key;return shellPage(p.label,p.title,`${heroHTML(p,score,r,left)}${statCards()}${pageHead(p.label,p.title)}${inspirationBlock()}<div class="grid">${backupReminder()}${nextCard()}<section class="panel span-5"><div class="panel-head"><h2>Ringkasan hari ini</h2><span class="pill">${esc(p.detail)}</span></div><div class="progress-row"><div class="progress-ring" style="--pct:${score}" data-label="${score}%" role="img" aria-label="${score} persen tercapai"></div><div class="progress-copy"><strong>${streak()} hari konsisten</strong><span>${score?`${score}% checklist tercatat`:'Mulai dari satu amalan'}</span></div></div><div class="progress-track"><i style="width:${score}%"></i></div></section><section class="panel span-7"><div class="panel-head"><h2>Shalat fardhu</h2><button class="link-btn" data-view="daily">Buka mutabaah →</button></div><div class="prayer-list">${PRAYERS.map((name,i)=>`<button class="prayer-item ${r.prayers[i]?'done':''}" data-action="prayer" data-value="${i}" aria-pressed="${r.prayers[i]}"><span>${name}</span><b>${r.prayers[i]?'Tercatat':'Belum'}</b></button>`).join('')}</div></section>${scheduleCard()}<section class="panel span-5"><div class="panel-head"><h2>Fokus fase ini</h2><span class="pill">${p.key==='prep'?'Pemanasan':p.key==='last'?'Malam ganjil':'Konsisten'}</span></div>${p.key==='prep'?`<p class="muted small">Catat qadha puasa, tuntaskan persiapan, lalu tetapkan niat Ramadhanmu.</p><div class="row-actions"><button class="btn" data-view="plan">Buka rencana pra-Ramadhan</button><span class="muted small">${db.settings.qadhaOwed-db.settings.qadhaDone} qadha tersisa</span></div>`:p.key==='last'?`<p class="muted small">Simpan doa pribadi dan tandai malam iktikaf tanpa kehilangan catatan.</p><div class="row-actions"><button class="btn" data-view="plan">Buka jurnal doa</button><span class="pill">${db.duas.length} doa tersimpan</span></div>`:p.key==='eid'||p.key==='post'?`<p class="muted small">Lanjutkan puasa Syawal dan kebiasaan yang ingin kamu jaga.</p><button class="btn" data-view="plan">Buka amalan Syawal</button>`:`<div class="stat-line"><strong>${r.pages}</strong><span>halaman Qur’an hari ini</span></div><p class="muted small">Target ${db.settings.quranGoal} juz · progres membantu mengukur ritme, bukan menilai diri.</p><button class="btn" data-view="daily">Catat amalan hari ini</button>`}</section><section class="panel span-5"><div class="panel-head"><h2>Hidrasi 2–4–2</h2><span class="pill">${r.water.filter(Boolean).length}/8 gelas</span></div><div class="water">${r.water.map((on,i)=>`<button data-action="water" data-value="${i}" class="${on?'on':''}" aria-label="Tandai gelas ${i+1}" aria-pressed="${on}">${on?'✓':i+1}</button>`).join('')}</div><div class="water-labels"><span>Sahur · 2</span><span>Berbuka · 4</span><span>Malam · 2</span></div></section><section class="panel span-12"><div class="panel-head"><h2>Pengingat hari ini</h2><button class="link-btn" data-view="plan">Jelajahi fitur →</button></div><div class="grid" style="margin:0"><div class="span-4"><div class="quote">“${esc(quote[0])}”<small>${esc(quote[1])}</small></div></div><div class="span-4"><div class="eyebrow">Keseimbangan</div><p class="muted small">Catat secukupnya. Nilai progres sebagai pengingat pribadi, bukan pembanding dengan orang lain.</p></div><div class="span-4"><div class="eyebrow">Privasi</div><p class="muted small">Data tersimpan di browser ini. Gunakan cadangan di Pengaturan sebelum mengganti perangkat.</p></div></div></section></div>`)}
    function daily(){const r=dayRecord(),phase=phaseInfo();document.documentElement.dataset.phase=phase.key;return shellPage('Mutabaah yaumiyah','Ibadah harianmu',`<div class="panel"><div class="form-grid"><label class="field"><span>Tanggal jurnal</span><input type="date" data-action="date" value="${selectedDate}" max="${keyOf(new Date())}"></label><label class="field"><span>Suasana hati (opsional)</span><select data-action="mood"><option value="0">Pilih suasana</option>${['Berat','Kurang baik','Biasa','Baik','Tenang'].map((m,i)=>`<option value="${i+1}" ${r.mood===i+1?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="section-title"><h2>Shalat fardhu</h2><span class="muted small">Tandai setelah menunaikan</span></div><div class="check-grid">${PRAYERS.map((n,i)=>taskHTML(n,r.prayers[i],'prayer',i)).join('')}</div><div class="section-title"><h2>Amalan sunnah dan harian</h2></div><div class="check-grid">${RAMADAN_TASKS.map((n,i)=>taskHTML(n,r.tasks[i],'task',i)).join('')}${taskHTML('Puasa sunnah hari ini',r.fast,'fast')}</div><div class="section-title"><h2>Tilawah Al-Qur’an</h2><span class="muted small">Target ${db.settings.quranGoal} juz</span></div><div class="row-actions"><div class="number-stepper"><button data-action="pages-step" data-value="-1" aria-label="Kurangi halaman">−</button><input class="text-input" type="number" min="0" max="1000" value="${r.pages}" data-action="pages" aria-label="Halaman dibaca"><button data-action="pages-step" data-value="1" aria-label="Tambah halaman">+</button></div><span class="muted small">halaman dibaca</span><label class="field" style="max-width:150px"><span>Juz selesai</span><input type="number" min="0" max="30" value="${r.juz||0}" data-action="juz"></label></div><div class="section-title"><h2>Sedekah</h2></div><label class="field" style="max-width:250px"><span>Nominal (Rp)</span><input type="number" min="0" step="1000" value="${r.sadaqah||0}" data-action="sadaqah"></label><div class="section-title"><h2>Hidrasi 2–4–2</h2><span class="muted small">${r.water.filter(Boolean).length} dari 8 gelas</span></div><div class="water">${r.water.map((on,i)=>`<button data-action="water" data-value="${i}" class="${on?'on':''}" aria-pressed="${on}">${on?'✓':i+1}</button>`).join('')}</div><div class="water-labels"><span>Sahur</span><span>Setelah berbuka</span><span>Malam</span></div><div class="section-title"><h2>Jurnal singkat</h2></div><label class="field"><span>Syukur, doa, atau refleksi hari ini</span><textarea data-action="note" placeholder="Tulis hanya yang ingin kamu simpan…">${esc(r.note)}</textarea></label><p class="muted small" style="margin:11px 0 0">Perubahan tersimpan otomatis di perangkat ini.</p></div>`)}
    function prepPlan(){const remain=Math.max(0,Number(db.settings.qadhaOwed)-Number(db.settings.qadhaDone)),deadline=db.settings.qadhaDeadline,daysLeft=Math.max(1,dateDiff(keyOf(new Date()),deadline)+1),dailyTarget=remain?Math.ceil(remain/daysLeft):0;return `<section class="panel"><div class="panel-head"><h2>Qadha puasa</h2><span class="pill">${remain} hari tersisa</span></div><p class="muted small">Buat target pelunasan sesuai kemampuan dan tenggat yang kamu tetapkan sendiri.</p><div class="form-grid"><label class="field"><span>Jumlah utang puasa</span><input type="number" min="0" max="365" data-setting="qadhaOwed" value="${db.settings.qadhaOwed}"></label><label class="field"><span>Sudah dibayar</span><input type="number" min="0" max="365" data-setting="qadhaDone" value="${db.settings.qadhaDone}"></label><label class="field"><span>Tanggal target</span><input type="date" data-setting="qadhaDeadline" value="${deadline}"></label></div><div class="notice" style="margin-top:13px">${remain?`Perkiraan target: ${dailyTarget} hari puasa per hari kalender sampai tenggat.`:'Qadha tercatat selesai.'} Atur ulang target bila tidak sesuai kemampuanmu.</div><div class="progress-track"><i style="width:${db.settings.qadhaOwed?Math.min(100,db.settings.qadhaDone/db.settings.qadhaOwed*100):0}%"></i></div></section><div class="section-title"><h2>Latihan puasa Sya’ban</h2><span class="muted small">${db.fasting.preRamadan.length} hari tercatat</span></div><section class="panel"><label class="field"><span>Tanggal puasa sunnah</span><input type="date" data-action="fast-date" max="${keyOf(new Date())}"></label><div class="list-row"><p>Senin–Kamis dan Ayyamul Bidh</p><span class="pill">${db.fasting.preRamadan.length} hari</span></div>${fastingCalendar('preRamadan')}</section><div class="section-title"><h2>Persiapan hati dan rencana</h2></div><section class="panel"><div class="check-grid">${PREP_CHECKS.map((n,i)=>taskHTML(n,db.prepDone.includes(i),'prep',i)).join('')}</div><div class="section-title"><h2>Visi Ramadhan</h2></div><div class="form-grid"><label class="field"><span>Target khatam (juz)</span><input type="number" min="1" max="30" data-setting="quranGoal" value="${db.settings.quranGoal}"></label><label class="field"><span>Target sedekah (Rp)</span><input type="number" min="0" step="10000" data-setting="sadaqahGoal" value="${db.settings.sadaqahGoal}"></label><label class="field"><span>Awal Ramadhan perkiraan</span><input type="date" data-setting="ramadanStart" value="${db.settings.ramadanStart}"></label></div></section>`}
    function fastingCalendar(kind){const dates=db.fasting[kind]||[];if(!dates.length)return '<p class="empty">Belum ada tanggal puasa tercatat.</p>';return `<div class="list-row"><p>Tanggal tersimpan</p><div class="row-actions">${dates.slice().sort().map(d=>`<span class="pill">${fmtDMY(d)} <button class="link-btn" data-action="fast-remove" data-kind="${kind}" data-date="${d}" aria-label="Hapus tanggal ${d}">×</button></span>`).join('')}</div></div>`}
    function zakat(){const fitrah=Number(db.settings.zakatFitrah)||0,nisab=Number(db.settings.nisab)||0;return `<section class="panel"><div class="panel-head"><h2>Kalkulator zakat</h2><span class="pill">Perkiraan, konfirmasi ke amil</span></div><div class="form-grid"><label class="field"><span>Zakat fitrah per orang (Rp)</span><input type="number" min="0" step="1000" data-setting="zakatFitrah" value="${fitrah}"></label><label class="field"><span>Jumlah jiwa</span><input type="number" min="1" value="${db.settings.dependents||1}" data-setting="dependents"></label><label class="field"><span>Harta untuk zakat maal (Rp)</span><input type="number" min="0" step="100000" data-setting="wealth" value="${db.settings.wealth||0}"></label><label class="field"><span>Nisab yang digunakan (Rp)</span><input type="number" min="0" step="100000" data-setting="nisab" value="${nisab}"></label></div><div class="grid"><div class="panel span-6" style="margin-top:14px"><div class="eyebrow">Estimasi zakat fitrah</div><div class="stat-line"><strong>Rp ${(fitrah*(Number(db.settings.dependents)||1)).toLocaleString('id-ID')}</strong></div></div><div class="panel span-6" style="margin-top:14px"><div class="eyebrow">Estimasi zakat maal 2,5%</div><div class="stat-line"><strong>Rp ${(Number(db.settings.wealth)>=nisab?Number(db.settings.wealth)*.025:0).toLocaleString('id-ID')}</strong></div></div></div><p class="notice" style="margin:14px 0 0">Perhitungan ini alat bantu sederhana, bukan fatwa. Pastikan nisab, haul, nilai bahan pokok, dan waktu pembayaran sesuai panduan amil setempat.</p></section>`}
    function tarawihPlan(){const goal=Math.max(0,Math.min(30,Number(db.settings.tarawihTarget)||0)),completed=Array.from({length:30},(_,i)=>db.days[keyPlus(db.settings.ramadanStart,i)]?.tasks?.[2]?i+1:null).filter(Boolean).length;return `<section class="panel" id="tarawih-plan"><div class="panel-head"><h2>Rencana Tarawih</h2><span class="pill">${completed}/30 malam tercatat</span></div><div class="form-grid"><label class="field"><span>Target malam yang ingin diupayakan</span><input type="number" min="0" max="30" data-setting="tarawihTarget" value="${goal}"></label><div class="field"><span>Progres target</span><div class="stat-line"><strong>${Math.min(completed,goal)}/${goal}</strong><span>malam</span></div></div></div><p class="muted small" style="margin:12px 0">Tandai malam di sini atau lewat checklist Tarawih harian. Sesuaikan target dengan kemampuan dan kondisi.</p><div class="calendar-strip">${Array.from({length:30},(_,i)=>{const k=keyPlus(db.settings.ramadanStart,i),done=!!db.days[k]?.tasks?.[2];return `<div class="day-cell ${done?'done':''}"><span>Malam</span><b>${i+1}</b><button class="link-btn" data-action="tarawih-night" data-value="${i+1}" aria-pressed="${done}">${done?'✓':'Tandai'}</button></div>`}).join('')}</div></section>`}
    function kajianNotes(){return `<section class="panel" id="kajian-notes"><div class="panel-head"><h2>Catatan kultum & kajian</h2><span class="pill">${db.kajian.length} catatan</span></div><div class="form-grid"><label class="field"><span>Judul atau pemateri</span><input id="kajian-title" maxlength="100" placeholder="Contoh: Menjaga istiqamah"></label><label class="field"><span>Tanggal</span><input id="kajian-date" type="date" value="${keyOf(new Date())}"></label><label class="field" style="grid-column:1/-1"><span>Pokok materi, kutipan, atau tindak lanjut</span><textarea id="kajian-note" maxlength="2000" placeholder="Tulis ringkasan yang ingin kamu ingat…"></textarea></label></div><div class="feature-actions"><button class="btn primary" data-action="kajian-add">Simpan catatan</button></div><div class="entry-list">${db.kajian.length?db.kajian.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(item=>`<div class="list-row"><div><p><strong>${esc(item.title)}</strong> <span class="muted small">· ${esc(item.date)}</span></p><p class="muted small" style="white-space:pre-wrap;margin-top:5px">${esc(item.note)}</p></div><button class="link-btn" data-action="kajian-delete" data-value="${esc(item.id)}">Hapus</button></div>`).join(''):'<p class="empty">Catatan kajian tersimpan privat di perangkat ini.</p>'}</div></section>`}
    function infaqLedger(){const total=db.infaq.reduce((sum,item)=>sum+(Number(item.amount)||0),0);return `<section class="panel" id="infaq-ledger"><div class="panel-head"><h2>Infaq & sedekah</h2><span class="pill">Total Rp ${total.toLocaleString('id-ID')}</span></div><div class="form-grid"><label class="field"><span>Nominal (Rp)</span><input id="infaq-amount" type="number" min="1" step="1000" placeholder="0"></label><label class="field"><span>Tanggal</span><input id="infaq-date" type="date" value="${keyOf(new Date())}"></label><label class="field" style="grid-column:1/-1"><span>Tujuan atau catatan (opsional)</span><input id="infaq-purpose" maxlength="120" placeholder="Contoh: infaq masjid"></label></div><div class="feature-actions"><button class="btn primary" data-action="infaq-add">Catat infaq</button></div><div class="entry-list">${db.infaq.length?db.infaq.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(item=>`<div class="list-row"><p><strong>Rp ${Number(item.amount).toLocaleString('id-ID')}</strong> · ${esc(item.date)}<br><span class="muted small">${esc(item.purpose||'Infaq / sedekah')}</span></p><button class="link-btn" data-action="infaq-delete" data-value="${esc(item.id)}">Hapus</button></div>`).join(''):'<p class="empty">Belum ada transaksi infaq yang dicatat.</p>'}</div></section>`}
    function zakatTracker(){const total=(Number(db.settings.zakatFitrah)||0)*(Number(db.settings.dependents)||1);return `<section class="panel" id="zakat-tracker"><div class="panel-head"><h2>Zakat fitrah</h2><span class="pill">Estimasi Rp ${total.toLocaleString('id-ID')}</span></div><label class="task"><input type="checkbox" data-action="zakat-paid" ${db.zakatFitrahPaid?'checked':''}><span>${db.zakatFitrahPaid?'Pembayaran ditandai selesai':'Tandai sudah menunaikan zakat fitrah'}</span></label><p class="muted small" style="margin:10px 0 0">Sesuaikan nilai zakat fitrah dengan ketetapan amil atau otoritas setempat. Estimasi ini hanya pengingat pribadi.</p></section>`}
    function eidCard(){const card=db.card;return `<div class="grid" id="eid-card-generator"><section class="panel span-6"><div class="panel-head"><h2>Generator kartu Lebaran</h2><span class="pill">Privat di perangkat</span></div><label class="field"><span>Nama penerima</span><input data-card-field="recipient" maxlength="80" value="${esc(card.recipient)}"></label><label class="field" style="margin-top:12px"><span>Nama pengirim</span><input data-card-field="sender" maxlength="80" value="${esc(card.sender||db.settings.displayName)}"></label><label class="field" style="margin-top:12px"><span>Pesan</span><textarea class="compact" data-card-field="message" maxlength="240">${esc(card.message)}</textarea></label><div class="feature-actions"><button class="btn primary" data-action="download-card">Unduh kartu PNG</button></div></section><section class="eid-preview span-6" id="card-preview"><div class="crescent" aria-hidden="true"><svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a7 7 0 0 0 10.5 10.5z"/></svg></div><div class="eyebrow">Idulfitri</div><h3>Mohon Maaf<br>Lahir & Batin</h3><p id="card-preview-recipient">${esc(card.recipient)}</p><p id="card-preview-message">${esc(card.message)}</p><p class="preview-from">Dari, <span id="card-preview-sender">${esc(card.sender||db.settings.displayName)}</span></p></section></div>`}
    function syawalTracker(){return `<section class="panel" id="syawal-tracker"><div class="panel-head"><h2>Puasa enam hari Syawal</h2><span class="pill">${Math.min(6,db.fasting.syawal.length)}/6 hari</span></div><label class="field"><span>Tanggal puasa selesai</span><input type="date" data-action="fast-date" max="${keyOf(new Date())}"></label>${fastingCalendar('syawal')}<div class="progress-track"><i style="width:${Math.min(100,db.fasting.syawal.length/6*100)}%"></i></div><p class="muted small" style="margin:10px 0 0">Catat enam hari puasa, berurutan atau terpisah. Pelaksanaan dapat disesuaikan dengan kondisi dan bimbingan yang kamu ikuti.</p></section>`}
    function planLinks(){return `<nav class="jump-links" aria-label="Bagian rencana"><a class="pill" href="#tarawih-plan">Tarawih</a><a class="pill" href="#doa-panel">Doa</a><a class="pill" href="#kajian-notes">Kajian</a><a class="pill" href="#infaq-ledger">Infaq</a><a class="pill" href="#zakat-tracker">Zakat fitrah</a><a class="pill" href="#eid-card-generator">Kartu Lebaran</a><a class="pill" href="#syawal-tracker">Puasa Syawal</a></nav>`}
    function planExtras(){return `${tarawihPlan()}<div class="section-title"><h2>Doa & dzikir</h2></div>${doaPanel()}<div class="section-title"><h2>Catatan dan amal</h2></div>${kajianNotes()}<div class="section-title"><h2>Pengelolaan sedekah</h2></div>${infaqLedger()}<div class="section-title"><h2>Menunaikan kewajiban</h2></div>${zakatTracker()}${eidCard()}${syawalTracker()}`}
    function lastTen(){return `<section class="panel"><div class="panel-head"><h2>Iktikaf dan malam terakhir</h2><label class="inline-field"><input type="checkbox" data-action="iktikaf" ${db['iktikaf']?'checked':''}><span>Mode iktikaf</span></label></div><p class="muted small">Mode ini menandai pilihanmu di perangkat ini. Atur waktu layar dan notifikasi perangkat secara mandiri.</p><div class="calendar-strip">${Array.from({length:10},(_,i)=>`<div class="day-cell ${db.iktikafDays?.includes(i+21)?'done':''}"><span>Malam</span><b>${i+21}</b><button class="link-btn" data-action="night" data-value="${i+21}">${db.iktikafDays?.includes(i+21)?'✓ Dicatat':'Tandai'}</button></div>`).join('')}</div></section><div class="section-title"><h2>Jurnal doa khusus</h2></div><section class="panel"><div class="row-actions"><input class="text-input" id="dua-input" placeholder="Doa atau harapan yang ingin kamu panjatkan" maxlength="240"><button class="btn primary" data-action="dua-add">Simpan doa</button></div>${db.duas.length?db.duas.map((d,i)=>`<div class="list-row"><p>${esc(d)}</p><button class="link-btn" data-action="dua-delete" data-value="${i}" aria-label="Hapus doa">Hapus</button></div>`).join(''):'<p class="empty">Doa pribadimu hanya disimpan di perangkat ini.</p>'}</section>`}
    function eid(){return `<div class="grid"><section class="panel span-6"><div class="panel-head"><h2>Panduan Shalat Id</h2><span class="pill">Ringkas</span></div><ol class="muted small" style="padding-left:19px"><li>Awali dengan niat dan takbiratul ihram.</li><li>Takbir tambahan pada rakaat pertama dan kedua mengikuti tuntunan setempat.</li><li>Dengarkan khutbah setelah shalat dan jaga adab silaturahmi.</li></ol><h3>Takbir</h3><p lang="ar" dir="rtl" style="font:22px/1.8 Georgia,serif">اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ</p><button class="btn" data-action="takbir">Putar panduan suara</button><p class="muted small" style="margin:9px 0 0">Suara menggunakan pembaca teks perangkat jika tersedia.</p></section><section class="panel span-6"><div class="panel-head"><h2>Kartu ucapan</h2></div><label class="field"><span>Nama penerima</span><input type="text" id="greet-name" placeholder="Keluarga dan sahabat"></label><p class="notice" id="greeting" style="margin:12px 0">Selamat Idulfitri. Mohon maaf lahir dan batin. Semoga Allah menerima amal ibadah kita.</p><button class="btn" data-action="copy-greeting">Salin ucapan</button></section></div><div class="section-title"><h2>Silaturahmi dan maaf</h2></div><section class="panel"><div class="row-actions"><input class="text-input" id="family-input" placeholder="Nama keluarga atau sahabat" maxlength="80"><button class="btn primary" data-action="family-add">Tambah</button></div>${db.family.length?db.family.map((f,i)=>`<div class="list-row"><label class="inline-field"><input type="checkbox" data-action="family-check" data-value="${i}" ${f.done?'checked':''}><span>${esc(f.name)}</span></label><button class="link-btn" data-action="family-delete" data-value="${i}">Hapus</button></div>`).join(''):'<p class="empty">Catat orang yang ingin kamu hubungi atau kunjungi.</p>'}</section>`}
    function postRamadan(){return `<section class="panel"><div class="panel-head"><h2>Puasa enam hari Syawal</h2><span class="pill">${db.fasting.syawal.length}/6 hari</span></div><label class="field"><span>Tanggal puasa selesai</span><input type="date" data-action="fast-date" max="${keyOf(new Date())}"></label>${fastingCalendar('syawal')}<div class="progress-track"><i style="width:${Math.min(100,db.fasting.syawal.length/6*100)}%"></i></div><p class="muted small" style="margin:10px 0 0">Boleh dicatat terpisah atau berurutan. Sesuaikan pelaksanaan dengan kondisi dan bimbingan yang kamu ikuti.</p></section><div class="section-title"><h2>Jaga kebiasaan sepanjang tahun</h2></div><section class="panel"><p class="muted small">Tandai kebiasaan hari ini. Catatan ini tidak mengukur nilai dirimu.</p><div class="check-grid">${HABITS.map((h,i)=>taskHTML(h,!!db.habits[`${keyOf(new Date())}-${i}`],'habit',i)).join('')}</div><div class="section-title"><h2>Safarnama</h2></div><div class="notice">Musafir dapat memiliki rukhsah terkait shalat dan puasa berdasarkan ketentuan yang berlaku. Perjalanan, jarak, durasi, dan kondisi tiap orang dapat berbeda; tanyakan kepada ustaz atau otoritas agama tepercaya. Aplikasi ini tidak menetapkan hukum untuk situasi personal.</div><div class="row-actions" style="margin-top:13px"><span class="pill">Jamak</span><span class="pill">Qashar</span><span class="pill">Puasa saat safar</span></div></section>`}
    function plan(){const p=phaseInfo();document.documentElement.dataset.phase=p.key;let content;if(p.key==='prep')content=prepPlan();else if(p.key==='last')content=lastTen()+`<div class="section-title"><h2>Pengingat zakat</h2></div>${zakat()}<div class="section-title"><h2>Safarnama</h2></div>${safarGuide()}`;else if(p.key==='eid')content=eid()+`<div class="section-title"><h2>Puasa Syawal</h2></div>${postRamadan()}`;else if(p.key==='post')content=postRamadan()+`<div class="section-title"><h2>Rapor Ramadhan</h2></div><button class="btn" data-view="report">Lihat evaluasi →</button>`;else content=`<div class="notice">${p.day<=10?'Mulai dengan target ringan dan konsisten.':p.day<=20?'Tinjau progres dan jaga diri dari kelelahan.':'Gunakan ruang malam untuk iktikaf dan doa.'}</div>${p.day<=20?`<div class="section-title"><h2>Progres pertengahan Ramadhan</h2></div><section class="panel"><div class="progress-row"><div class="progress-ring" style="--pct:${monthProgress()}" data-label="${monthProgress()}%"></div><div class="progress-copy"><strong>${monthProgress()}% catatan tersedia</strong><span>Hari dengan jurnal dari ${Math.max(1,p.day)} hari berjalan.</span></div></div><p class="muted small" style="margin:13px 0 0">${monthProgress()<35?'Bila sedang lelah, pilih satu amalan singkat dan istirahat yang cukup.':'Pertahankan ritme yang realistis; tidak perlu mengejar angka.'}</p><button class="btn" data-action="gentle">Tampilkan pengingat lembut</button></section>`:''}${safarGuide()}<div class="section-title"><h2>Hitung zakat</h2></div>${zakat()}`;return shellPage('Rencana fase',p.label,content)}
    function safarGuide(){return `<section class="panel"><div class="panel-head"><h2>Safarnama</h2><span class="pill">Panduan musafir</span></div><p class="muted small">Ringkasan umum, bukan penetapan hukum untuk keadaan tertentu.</p><div class="list-row"><p><strong>Jamak</strong><br><span class="muted small">Menggabungkan dua shalat pada waktu yang dibolehkan sesuai syarat.</span></p></div><div class="list-row"><p><strong>Qashar</strong><br><span class="muted small">Meringkas shalat empat rakaat sesuai ketentuan safar yang diikuti.</span></p></div><div class="list-row"><p><strong>Puasa saat bepergian</strong><br><span class="muted small">Pertimbangkan kondisi perjalanan, kemampuan, dan panduan tepercaya.</span></p></div><p class="notice" style="margin:12px 0 0">Ketentuan dapat berbeda menurut mazhab, jarak, niat menetap, dan kondisi. Konfirmasikan kepada pembimbing agama atau otoritas setempat.</p></section>`}
    function monthProgress(){const start=db.settings.ramadanStart;let n=0,all=0;for(let i=0;i<30;i++){const k=keyPlus(start,i);if(k>keyOf(new Date()))break;all++;if(db.days[k]&&(todayScore(db.days[k])>0||db.days[k].note))n++}return all?Math.round(n/all*100):0}
    function keyPlus(k,n){const d=new Date(`${k}T12:00:00`);d.setDate(d.getDate()+n);return keyOf(d)}
    function report(){const days=Object.entries(db.days).filter(([,r])=>r.prayers.some(Boolean)||r.pages||r.note||Object.values(r.tasks).some(Boolean));const scores=days.map(([,r])=>todayScore(r)),avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;const daily=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const k=keyOf(d);return{label:d.toLocaleDateString('id-ID',{weekday:'short'}),score:db.days[k]?todayScore(db.days[k]):0}});const pages=days.reduce((a,[,r])=>a+(Number(r.pages)||0),0),sad=days.reduce((a,[,r])=>a+(Number(r.sadaqah)||0),0);const phase=phaseInfo();document.documentElement.dataset.phase=phase.key;return shellPage('Rapor spiritual','Lihat perjalananmu',`<div class="grid"><section class="panel span-4"><div class="eyebrow">Hari tercatat</div><div class="stat-line"><strong>${days.length}</strong><span>hari jurnal</span></div></section><section class="panel span-4"><div class="eyebrow">Rata-rata checklist</div><div class="stat-line"><strong>${avg}%</strong><span>dari jurnal tercatat</span></div></section><section class="panel span-4"><div class="eyebrow">Streak saat ini</div><div class="stat-line"><strong>${streak()}</strong><span>hari beruntun</span></div></section><section class="panel span-8"><div class="panel-head"><h2>Mutabaah 7 hari terakhir</h2><span class="pill">Persentase per hari</span></div><div class="chart">${daily.map(d=>`<div class="chart-col"><b>${d.score}%</b><i style="height:${d.score}%"></i><span>${d.label}</span></div>`).join('')}</div></section><section class="panel span-4"><div class="panel-head"><h2>Akumulasi</h2></div><div class="list-row"><p>Halaman Qur’an</p><strong>${pages}</strong></div><div class="list-row"><p>Sedekah (Rp)</p><strong>${sad.toLocaleString('id-ID')}</strong></div><div class="list-row"><p>Puasa Syawal</p><strong>${db.fasting.syawal.length}/6</strong></div></section><section class="panel span-12"><div class="eyebrow">Refleksi</div><h2>Progres bukan perlombaan.</h2><p class="muted small">Angka di atas hanya ringkasan catatan pribadimu, bukan penilaian kualitas iman atau ibadah. Simpan laporan dengan aman dan tinjau sesuai tujuanmu.</p><button class="btn" data-action="export">Unduh cadangan data</button></section></div>`)}
    function settings(){const p=phaseInfo();document.documentElement.dataset.phase=p.key;return shellPage('Pengaturan & privasi','Kendali tetap di tanganmu',`<div class="grid"><section class="panel span-7"><div class="panel-head"><h2>Profil dan tanggal</h2></div><div class="form-grid"><label class="field"><span>Nama panggilan</span><input type="text" data-setting="displayName" maxlength="40" value="${esc(db.settings.displayName)}"></label><label class="field"><span>Awal Ramadhan perkiraan</span><input type="date" data-setting="ramadanStart" value="${db.settings.ramadanStart}"></label><label class="field"><span>Nama kota (opsional)</span><input type="text" data-setting="city" value="${esc(db.settings.city)}" placeholder="Untuk label jadwal"></label><label class="field"><span>Koreksi tanggal Hijriah (hari)</span><select data-setting="hijriOffset">${[-2,-1,0,1,2].map(v=>`<option value="${v}" ${(db.settings.hijriOffset||0)===v?'selected':''}>${v>0?'+'+v:v}</option>`).join('')}</select></label></div><p class="muted small" style="margin:12px 0 0">Hari ini kira-kira ${esc(formatHijri(keyOf(new Date()),db.settings.hijriOffset)||'—')}. Tanggal Hijriah memakai kalender Umm al-Qura sebagai perkiraan. Awal Ramadhan dan Syawal di Indonesia mengikuti sidang isbat Kemenag atau ketetapan ormas Anda, jadi perbarui tanggal awal Ramadhan setelah ada penetapan resmi.</p><div class="row-actions" style="margin-top:10px"><button class="btn" data-action="estimate-ramadan">Isi perkiraan awal Ramadhan</button></div></section><section class="panel span-12"><div class="panel-head"><h2>Privasi dan cadangan</h2><span class="pill">Penyimpanan lokal</span></div><p class="muted small">Jurnal dan progres tersimpan di penyimpanan browser perangkat ini. Tidak ada akun, sinkronisasi cloud, atau pengiriman catatan ibadah. Menghapus data browser dapat menghapus catatan.</p>${storageNote()}<div class="row-actions"><button class="btn primary" data-action="export">Unduh cadangan JSON</button><button class="btn" data-action="import">Pulihkan cadangan</button><button class="btn quiet danger" data-action="reset">Hapus semua data</button><input type="file" id="import-file" accept="application/json" hidden></div></section><section class="panel span-12"><div class="panel-head"><h2>Pengingat waktu salat</h2><span class="pill">${db.settings.reminders?'Aktif':'Nonaktif'}</span></div><p class="muted small">Pengingat berbunyi tepat waktu selama RamadhanPro terbuka di browser atau masih berjalan di latar belakang. Browser dapat menghentikannya saat layar terkunci atau baterai dihemat, dan aplikasi web tidak bisa menggantikan adzan. Untuk jadwal yang andal, tetap gunakan alarm perangkat atau aplikasi adzan.</p><p class="muted small">${esc(reminderStatus())}</p><div class="row-actions"><button class="btn primary" data-action="reminders-toggle">${db.settings.reminders?'Matikan pengingat':'Aktifkan pengingat'}</button><button class="btn" data-action="notify-test">Kirim notifikasi uji</button></div></section></div>`)}
    function render(){syncInstall();const p=phaseInfo(),theme=db.settings.theme==='muslimah'?'muslimah':'muslim',mode=db.settings.mode==='light'?'light':'dark';document.documentElement.dataset.phase=p.key;document.documentElement.dataset.theme=theme;document.documentElement.dataset.mode=mode;const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.content=mode==='light'?(theme==='muslimah'?'#e7c7ee':'#d3c8f5'):(theme==='muslimah'?'#2a1740':'#1f1840');{const who=db.settings.displayName||'Sahabat';document.getElementById('profile-name').textContent=who;document.getElementById('side-initials').textContent=initialsOf(who);document.getElementById('side-hi').textContent=`Hi, ${who.split(/\s+/)[0]}! 👋`}const views={home,calendar,daily,plan,report,settings};patchHTML(document.getElementById('side-nav'),navHTML(),'nav');patchHTML(document.getElementById('mobile-nav'),mobileNavHTML(),'nav');patchHTML(document.getElementById('main'),views[view]()+footerHTML(),view);}
    function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
    function update(mutator){mutator();save();render()}
    function exportData(){db.lastBackupAt=Date.now();db.backupSnoozeUntil=0;save();const payload={app:'ramadhanpro',exportedAt:new Date().toISOString(),...db};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`ramadhanpro-cadangan-${keyOf(new Date())}.json`;a.click();URL.revokeObjectURL(a.href);notify('Cadangan berhasil diunduh');render()}
    function hijriLabel(){const text=formatHijri(keyOf(new Date()),db.settings.hijriOffset);return text?`<span class="hijri">${esc(text)}</span>`:''}
    function reminderStatus(){
      const parts=[];
      if(!('Notification'in window))parts.push('Browser ini tidak mendukung notifikasi.');
      else parts.push(Notification.permission==='granted'?'Izin notifikasi diberikan.':Notification.permission==='denied'?'Izin notifikasi diblokir di pengaturan browser.':'Izin notifikasi belum diminta.');
      if(!prayerSchedule())parts.push('Atur lokasi agar jadwal dapat dihitung.');
      return parts.join(' ');
    }
    const FIRED_KEY='ramadhanpro-fired-reminders';
    function readFired(){try{return JSON.parse(localStorage.getItem(FIRED_KEY)||'[]')}catch{return[]}}
    async function showSystemNotification(title,body,tag){
      try{
        const registration=await navigator.serviceWorker?.getRegistration?.();
        if(registration?.showNotification){await registration.showNotification(title,{body,tag,icon:'icon-192.png',badge:'icon-192.png'});return true}
        if('Notification'in window&&Notification.permission==='granted'){new Notification(title,{body,tag,icon:'icon-192.png'});return true}
      }catch{}
      return false;
    }
    function checkReminders(){
      if(!db.settings.reminders||!('Notification'in window)||Notification.permission!=='granted')return;
      const schedule=prayerSchedule();
      if(!schedule)return;
      const now=Date.now(),fired=pruneFired(readFired(),now),ramadan=['ramadan','last'].includes(phaseInfo().key);
      const due=dueReminders(schedule.epoch,now,fired,{ramadan});
      if(!due.length)return;
      try{localStorage.setItem(FIRED_KEY,JSON.stringify([...fired,...due.map(item=>item.id)]))}catch{}
      for(const item of due){
        const message=reminderMessage(item.name,{ramadan});
        if(document.visibilityState==='visible')notify(message.title);
        else showSystemNotification(message.title,message.body,item.id);
      }
    }
    setInterval(checkReminders,20000);
    function backupDate(ms){return fmtDMY(ms)}
    function backupReminder(){if(!backupReminderDue(db))return '';const last=db.lastBackupAt?`Cadangan terakhir ${backupDate(db.lastBackupAt)}.`:'Kamu belum pernah mengunduh cadangan.';return `<section class="panel span-12" id="backup-reminder" role="note"><div class="panel-head"><h2>Amankan catatanmu</h2><span class="pill">Penyimpanan lokal</span></div><p class="muted small">${last} Catatan hanya tersimpan di perangkat ini dan bisa hilang jika data browser dihapus. Unduh cadangan agar tetap aman.</p><div class="row-actions"><button class="btn primary" data-action="export">Unduh cadangan</button><button class="btn quiet" data-action="backup-snooze">Ingatkan ${BACKUP_SNOOZE_DAYS} hari lagi</button></div></section>`}
    function storageNote(){const s=storageInfo,parts=[s.persisted===true?'Penyimpanan dilindungi: browser tidak akan menghapus catatan secara otomatis.':s.persisted===false?'Penyimpanan belum dijamin: browser dapat menghapusnya jika memori perangkat menipis.':'Status perlindungan penyimpanan tidak tersedia di browser ini.'];if(s.usage!=null)parts.push(`Ruang yang dipakai situs ini ${formatBytes(s.usage)}.`);parts.push(db.lastBackupAt?`Cadangan terakhir: ${backupDate(db.lastBackupAt,true)}.`:'Belum ada cadangan yang diunduh.');return `<p class="muted small" id="storage-note">${esc(parts.join(' '))}</p>${s.persisted===false?'<div class="row-actions"><button class="btn" data-action="persist">Lindungi penyimpanan</button></div>':''}`}
    function addFast(kind,date){if(!date)return;if(db.fasting[kind].includes(date)){notify('Tanggal itu sudah tercatat');return}if(kind==='syawal'&&db.fasting.syawal.length>=6){notify('Target enam hari Syawal sudah tercatat');return}db.fasting[kind].push(date);db.fasting[kind].sort();save();render();notify('Tanggal puasa dicatat')}
    function locatePrayer(){if(!navigator.geolocation){notify('Browser ini tidak menyediakan akses lokasi');return}notify('Meminta izin lokasi…');navigator.geolocation.getCurrentPosition(position=>{db.settings.latitude=Number(position.coords.latitude.toFixed(6));db.settings.longitude=Number(position.coords.longitude.toFixed(6));save();render();notify('Lokasi tersimpan di perangkat')},()=>notify('Izin lokasi tidak diberikan. Masukkan koordinat secara manual.'))}
    /* ==================================================================
       EVENT ROUTER — satu pintu untuk semua interaksi (klik, ubah, input).
       Fitur baru cukup menambah satu entri di CLICK_ACTIONS, tanpa
       listener baru dan tanpa stopImmediatePropagation.
       ================================================================== */
    const CLICK_ACTIONS={
      prayer(t){const i=Number(t.dataset.value);update(()=>{const r=dayRecord();r.prayers[i]=!r.prayers[i]})},
      water(t){const i=Number(t.dataset.value);update(()=>{const r=dayRecord();r.water[i]=!r.water[i]})},
      'pages-step'(t){update(()=>{const r=dayRecord();r.pages=Math.max(0,(Number(r.pages)||0)+Number(t.dataset.value))})},
      'fast-date'(){addFast('preRamadan',document.querySelector('[data-action="fast-date"]').value)},
      'fast-remove'(t){update(()=>db.fasting[t.dataset.kind]=db.fasting[t.dataset.kind].filter(d=>d!==t.dataset.date))},
      prep(t){update(()=>{const i=Number(t.dataset.value);db.prepDone=db.prepDone.includes(i)?db.prepDone.filter(v=>v!==i):[...db.prepDone,i]})},
      iktikaf(){update(()=>db.iktikaf=!db.iktikaf)},
      night(t){update(()=>{db.iktikafDays||=[];const n=Number(t.dataset.value);db.iktikafDays=db.iktikafDays.includes(n)?db.iktikafDays.filter(d=>d!==n):[...db.iktikafDays,n]})},
      'dua-add'(){const value=document.getElementById('dua-input').value.trim();if(value)update(()=>db.duas.push(value));else notify('Tulis doa terlebih dahulu')},
      'dua-delete'(t){update(()=>db.duas.splice(Number(t.dataset.value),1))},
      'family-add'(){const name=document.getElementById('family-input').value.trim();if(name)update(()=>db.family.push({name,done:false}));else notify('Tulis nama terlebih dahulu')},
      'family-delete'(t){update(()=>db.family.splice(Number(t.dataset.value),1))},
      'calendar-month'(el){const [y,m]=calMonth.split('-').map(Number);calMonth=keyOf(new Date(y,m-1+Number(el.dataset.delta),1,12)).slice(0,7);render()},
      'calendar-today'(){selectedDate=keyOf(new Date());calMonth=selectedDate.slice(0,7);render()},
      async 'copy-greeting'(){const name=document.getElementById('greet-name').value.trim(),text=`${name?`Untuk ${name}, `:''}Selamat Idulfitri. Mohon maaf lahir dan batin. Semoga Allah menerima amal ibadah kita.`;try{await navigator.clipboard.writeText(text);notify('Ucapan disalin')}catch{notify(text)}},
      takbir(){const text='Allahu akbar, Allahu akbar, la ilaha illallah, wallahu akbar. Allahu akbar wa lillahil hamd.';if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text))}else notify('Pembaca suara tidak tersedia')},
      gentle(){notify('Pilih satu amal kecil, tarik napas, dan beri tubuh waktu untuk beristirahat.')},
      'export'(){exportData()},
      'import'(){document.getElementById('import-file').click()},
      'reset'(){if(confirm('Hapus seluruh catatan RamadhanPro dari perangkat ini? Tindakan ini tidak dapat dibatalkan.')){localStorage.removeItem(KEY);db=structuredClone(defaults);save();render();notify('Data dihapus')}},
      async install(){
        const mode=currentInstallMode();
        if(mode!=='prompt'){notify(installMessage(mode));return}
        const event=installEvent;
        installEvent=null;syncInstall();
        try{
          await event.prompt();
          const choice=await event.userChoice;
          notify(choice?.outcome==='accepted'?'Memasang RamadhanPro…':'Pemasangan dibatalkan. Kamu bisa memasangnya kapan saja.');
        }catch{notify('Pemasangan gagal. Coba lagi sebentar lagi.')}
      },
      async 'reminders-toggle'(){
        if(db.settings.reminders){update(()=>db.settings.reminders=false);notify('Pengingat dimatikan');return}
        if(!('Notification'in window)){notify('Browser ini tidak mendukung notifikasi');return}
        if(!prayerSchedule()){notify('Atur lokasi lebih dulu agar jadwal bisa dihitung');return}
        const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
        if(permission==='granted'){update(()=>db.settings.reminders=true);notify('Pengingat aktif selama aplikasi terbuka')}
        else{notify('Izin notifikasi tidak diberikan');render()}
      },
      async 'notify-test'(){
        if(!('Notification'in window)){notify('Browser ini tidak mendukung notifikasi');return}
        const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();
        if(permission!=='granted'){notify('Izin notifikasi tidak diberikan');render();return}
        const shown=await showSystemNotification('RamadhanPro','Notifikasi uji berhasil.','rp-test');
        notify(shown?'Notifikasi uji dikirim':'Notifikasi tidak dapat ditampilkan');render();
      },
      'estimate-ramadan'(){
        const estimate=estimateRamadanStart(keyOf(new Date()),db.settings.hijriOffset||0);
        if(!estimate){notify('Perkiraan tidak tersedia di browser ini');return}
        update(()=>db.settings.ramadanStart=estimate);
        notify(`Awal Ramadhan diisi ${backupDate(dateFromKey(estimate).getTime(),true)} (perkiraan). Perbarui setelah sidang isbat.`);
      },
      'tarawih-night'(t){const date=keyPlus(db.settings.ramadanStart,Number(t.dataset.value)-1);update(()=>{const record=dayRecord(date);record.tasks[2]=!record.tasks[2]})},
      'kajian-add'(){const title=document.getElementById('kajian-title').value.trim(),date=document.getElementById('kajian-date').value,note=document.getElementById('kajian-note').value.trim();if(!title||!note){notify('Isi judul dan ringkasan kajian terlebih dahulu');return}update(()=>db.kajian.push({id:`k-${Date.now().toString(36)}`,title,date:date||keyOf(new Date()),note}))},
      'kajian-delete'(t){update(()=>db.kajian=db.kajian.filter(item=>item.id!==t.dataset.value))},
      'infaq-add'(){const amount=Number(document.getElementById('infaq-amount').value),date=document.getElementById('infaq-date').value,purpose=document.getElementById('infaq-purpose').value.trim();if(!Number.isFinite(amount)||amount<=0){notify('Masukkan nominal infaq yang valid');return}update(()=>db.infaq.push({id:`i-${Date.now().toString(36)}`,amount,date:date||keyOf(new Date()),purpose}))},
      'infaq-delete'(t){update(()=>db.infaq=db.infaq.filter(item=>item.id!==t.dataset.value))},
      'backup-snooze'(){update(()=>db.backupSnoozeUntil=Date.now()+BACKUP_SNOOZE_DAYS*86400000)},
      async persist(){const ok=await requestPersistence();notify(ok?'Penyimpanan kini dilindungi':'Browser belum memberi izin. Pasang aplikasi ke layar utama lalu coba lagi.');refreshStorage()},
      'download-card'(){downloadCard()},
    };

    /* Aksi yang boleh dipicu oleh elemen apa pun (bukan hanya <button>) */
    const PRAYER_CLICK_SELECTOR='[data-action="calendar-select"],[data-action="calendar-open"],[data-action="locate-prayer"],[data-action="calculate-prayer"]';
    function handlePrayerClick(el){
      const a=el.dataset.action;
      if(a==='calendar-select'){selectedDate=el.dataset.date;render()}
      else if(a==='calendar-open'){selectedDate=el.dataset.date;view='daily';render()}
      else if(a==='locate-prayer')locatePrayer();
      else if(a==='calculate-prayer'){const result=prayerSchedule();if(result)notify(`Jadwal dihitung dengan ${result.method}`);else notify('Lengkapi koordinat dan zona waktu yang valid.');render()}
    }

    async function handleButtonClick(e){
      const button=e.target.closest('button');
      if(!button)return;
      if(button.dataset.view){view=button.dataset.view;if(view==='calendar')calMonth=null;render();window.scrollTo(0,0);return}
      const handler=CLICK_ACTIONS[button.dataset.action];
      if(handler)await handler(button,e);
    }

    function handleDialogClick(e){
      const target=e.target;
      const close=target.closest('[data-close-dialog]');
      if(close){close.closest('dialog')?.close();return}
      const trigger=target.closest('[data-dialog]');
      if(trigger)document.getElementById(trigger.dataset.dialog)?.showModal();
      const tab=target.closest('[data-tab]');
      if(tab){
        const dialog=tab.closest('dialog');
        dialog.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('on',b===tab));
        dialog.querySelectorAll('[data-pane]').forEach(x=>x.hidden=x.dataset.pane!==tab.dataset.tab);
        return;
      }
      if(target.matches('dialog.help-dialog,dialog.app-dialog'))target.close();
    }

    async function onClick(e){
      const choice=e.target.closest('[data-theme-choice],[data-mode-choice]');
      if(choice){
        if(choice.dataset.themeChoice)db.settings.theme=choice.dataset.themeChoice;
        if(choice.dataset.modeChoice)db.settings.mode=choice.dataset.modeChoice;
        save();render();return;
      }
      const prayerEl=e.target.closest(PRAYER_CLICK_SELECTOR);
      if(prayerEl){handlePrayerClick(prayerEl);return}
      await handleButtonClick(e);
      handleDialogClick(e);
    }

    const BACKUP_ERRORS={too_big:'Berkas terlalu besar untuk cadangan RamadhanPro.',not_json:'Berkas bukan JSON yang valid.',not_backup:'Berkas ini bukan cadangan RamadhanPro.',newer:'Cadangan dibuat oleh versi RamadhanPro yang lebih baru. Perbarui aplikasi lebih dulu.'};
    function importBackup(input){
      const file=input.files[0];
      if(!file)return;
      if(file.size>MAX_BACKUP_BYTES){notify(BACKUP_ERRORS.too_big);input.value='';return}
      const reader=new FileReader();
      reader.onload=()=>{
        const result=validateBackup(String(reader.result),defaults);
        if(!result.ok)notify(BACKUP_ERRORS[result.reason]||'File cadangan tidak valid');
        else{
          const sum=result.summary,when=result.exportedAt?` (diunduh ${backupDate(result.exportedAt,true)})`:'',skipped=result.dropped?`\n${result.dropped} entri yang tidak valid akan diabaikan.`:'';
          if(confirm(`Pulihkan cadangan${when}?\n\nIsi: ${sum.activeDays} hari tercatat, ${sum.infaq} infaq, ${sum.kajian} catatan kajian, ${sum.duas} doa.${skipped}\n\nData saat ini di perangkat akan diganti.`)){db=mergeSnapshot(result.data);save();render();notify('Cadangan berhasil dipulihkan')}
        }
        input.value='';
      };
      reader.onerror=()=>{notify('Berkas tidak bisa dibaca');input.value=''};
      reader.readAsText(file);
    }

    function onChange(e){
      const el=e.target,a=el.dataset.action;

      const cityPick=el.closest('[data-city-pick]');
      if(cityPick&&cityPick.value!==''){
        const c=CITIES[Number(cityPick.value)];
        if(!c)return;
        Object.assign(db.settings,{city:c[0],latitude:c[1],longitude:c[2],timezone:c[3]});
        if(c[4])db.settings.prayerMethod=c[4];
        save();render();notify(`Lokasi diatur ke ${c[0]}`);return;
      }

      const prayerField=el.closest('[data-prayer-setting]');
      if(prayerField){
        const key=prayerField.dataset.prayerSetting;
        if(key.startsWith('adjust.')){
          const part=key.slice(7),n=Math.round(Number(prayerField.value));
          db.settings.prayerAdjust||={};
          if(ADJUST_FIELDS.some(f=>f[0]===part))db.settings.prayerAdjust[part]=Number.isFinite(n)?Math.max(-30,Math.min(30,n)):0;
          save();render();return;
        }
        const value=['latitude','longitude','imsakOffset'].includes(key)?(prayerField.value===''?null:Number(prayerField.value)):prayerField.value;
        db.settings[key]=value;save();render();return;
      }

      if(a==='fast-date'&&el.closest('#syawal-tracker')){addFast('syawal',el.value);return}
      if(el.id==='import-file'){importBackup(el);return}
      if(a==='zakat-paid'){update(()=>db.zakatFitrahPaid=el.checked);return}

      if(a==='prayer'||a==='task'||a==='fast'||a==='habit'||a==='prep'||a==='water'){
        const checked=el.checked;
        update(()=>{
          const i=Number(el.dataset.value);
          if(a==='prayer')dayRecord().prayers[i]=checked;
          else if(a==='task')dayRecord().tasks[i]=checked;
          else if(a==='fast')dayRecord().fast=checked;
          else if(a==='water')dayRecord().water[i]=checked;
          else if(a==='prep')db.prepDone=db.prepDone.includes(i)?db.prepDone.filter(x=>x!==i):[...db.prepDone,i];
          else db.habits[`${keyOf(new Date())}-${i}`]=checked;
        });
      }
      else if(a==='date'){selectedDate=el.value;render()}
      else if(a==='mood')update(()=>dayRecord().mood=Number(el.value));
      else if(a==='pages')update(()=>dayRecord().pages=Math.max(0,Number(el.value)||0));
      else if(a==='juz')update(()=>dayRecord().juz=Math.max(0,Math.min(30,Number(el.value)||0)));
      else if(a==='sadaqah')update(()=>dayRecord().sadaqah=Math.max(0,Number(el.value)||0));
      else if(a==='fast-date')addFast(phaseInfo().key==='prep'?'preRamadan':'syawal',el.value);
      else if(a==='family-check')update(()=>db.family[Number(el.dataset.value)].done=el.checked);
      else if(a==='note')update(()=>dayRecord().note=el.value);
      else if(a==='pages-step'){}
      else if(el.dataset.setting)update(()=>{
        const key=el.dataset.setting,textFields=['displayName','city','ramadanStart','qadhaDeadline','theme'].includes(key),value=textFields?el.value:el.value===''?0:Number(el.value);
        db.settings[key]=value;render();
      });
    }

    function onInput(e){
      const el=e.target,a=el.dataset.action;
      if(a==='note'){dayRecord().note=el.value;save()}
      else if(el.dataset.setting&&['displayName','city'].includes(el.dataset.setting)){
        db.settings[el.dataset.setting]=el.value;save();
        document.getElementById('profile-name').textContent=el.value||'Sahabat';
      }
      const field=el.dataset.cardField;
      if(field){
        db.card[field]=el.value;save();
        const preview=document.getElementById(`card-preview-${field}`);
        if(preview)preview.textContent=el.value||(field==='sender'?db.settings.displayName:'');
      }
    }

    document.addEventListener('click',onClick);
    document.addEventListener('change',onChange);
    document.addEventListener('input',onInput);
    function downloadCard(){const card=db.card,canvas=document.createElement('canvas');canvas.width=1200;canvas.height=750;const context=canvas.getContext('2d'),background=context.createLinearGradient(0,0,1200,750);background.addColorStop(0,'#142d27');background.addColorStop(.58,'#294235');background.addColorStop(1,'#503a24');context.fillStyle=background;context.fillRect(0,0,1200,750);context.strokeStyle='rgba(239,187,120,.45)';context.lineWidth=2;for(const [x,y,r] of [[85,90,220],[1110,690,260]]){context.beginPath();context.arc(x,y,r,0,Math.PI*2);context.stroke();context.beginPath();context.arc(x,y,r+28,0,Math.PI*2);context.stroke()}context.textAlign='center';context.fillStyle='#efbb78';context.font='48px Georgia';context.fillText('☾',600,145);context.font='700 24px Sora, sans-serif';context.fillText('IDULFITRI',600,205);context.fillStyle='#f4d49c';context.font='700 58px Sora, sans-serif';context.fillText('Mohon Maaf Lahir & Batin',600,295);context.fillStyle='#f1f3eb';context.font='500 32px "Inter", sans-serif';if(card.recipient)context.fillText(`Untuk ${card.recipient}`,600,365,{maxWidth:1000});const words=(card.message||'').split(/\s+/),lines=[];let line='';for(const word of words){const test=line?`${line} ${word}`:word;if(context.measureText(test).width>850&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);context.font='400 27px "Inter", sans-serif';context.fillStyle='#f1f3eb';lines.slice(0,4).forEach((text,i)=>context.fillText(text,600,430+i*40,{maxWidth:900}));context.fillStyle='#efbb78';context.font='600 23px "Inter", sans-serif';context.fillText(`Dari, ${card.sender||db.settings.displayName}`,600,650,{maxWidth:1000});canvas.toBlob(blob=>{if(!blob){notify('Kartu gagal dibuat');return}const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='kartu-lebaran-ramadhanpro.png';link.click();URL.revokeObjectURL(link.href);notify('Kartu Lebaran berhasil diunduh')},'image/png')}

    function doaPanel(){return `<section class="panel" id="doa-panel"><div class="panel-head"><h2>Doa pilihan Ramadhan</h2><span class="pill">${DOA.length} doa</span></div>${DOA.map(d=>`<details class="doa"><summary>${esc(d[0])}</summary><p class="ar" lang="ar" dir="rtl">${d[1]}</p><p class="lat">${esc(d[2])}</p><p class="muted small" style="margin:0 0 6px">${esc(d[3])}</p><span class="src">${esc(d[4])}</span></details>`).join('')}</section>`}
    function nextEvent(){const s=prayerSchedule();if(!s)return null;const now=Date.now();let e=Object.entries(s.epoch).find(([,t])=>t>now);if(!e){const t=prayerSchedule(keyPlus(keyOf(new Date()),1));e=t&&Object.entries(t.epoch)[0]}return e?{name:e[0],at:e[1]}:null}
    function fmtCountdown(ms){const s=Math.max(0,Math.floor(ms/1000));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(v=>String(v).padStart(2,'0')).join(':')}
    function nextCard(){const n=nextEvent();if(!n)return '';const ram=['ramadan','last'].includes(phaseInfo().key),label=ram&&n.name==='Maghrib'?'Menuju waktu berbuka':ram&&n.name==='Imsak'?'Menuju imsak':n.name==='Terbit'?'Menuju terbit matahari':`Menuju ${n.name}`,clock=new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:db.settings.timezone||undefined}).format(n.at);return `<section class="panel span-12 next-card" aria-live="off"><div><div class="eyebrow">${label}</div><div class="next-time" data-at="${n.at}">${fmtCountdown(n.at-Date.now())}</div></div><div class="next-meta"><b>${esc(n.name)}</b> · ${clock}<br><span class="muted small">${esc(db.settings.city||'Lokasi tersimpan')}</span></div></section>`}
    setInterval(()=>{document.querySelectorAll('[data-at]').forEach(el=>{const d=Number(el.dataset.at)-Date.now();if(d<=0){if(view==='home')render();return}el.textContent=fmtCountdown(d)})},1000);
    const SOC=[['Instagram','https://instagram.com/kurniapedia','<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/>'],['TikTok','https://www.tiktok.com/@kurniapedia','<path d="M14 3v11.5a3.5 3.5 0 1 1-3.5-3.5M14 3c.4 2.4 2 4 4.5 4.3"/>'],['Kurniapedia','https://kurniapedia.my.id/','<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/>'],['WhatsApp','https://wa.me/6285870906050','<path d="M20 11.5a8 8 0 0 1-11.7 7L4 20l1.5-4.2A8 8 0 1 1 20 11.5z"/>']];
    function footerHTML(){return `<footer class="app-footer"><div class="social">${SOC.map(([n,u,d])=>`<a href="${u}" target="_blank" rel="noopener noreferrer" aria-label="${n}" title="${n}"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg></a>`).join('')}</div><p>Crafted with <span class="heart">♥</span> by Kurniapedia 2026</p></footer>`}
    /* Pemasangan PWA: event dari browser disimpan, tombol "Pasang" langsung memunculkan jendela pemasangan. */
    let installEvent=window.__installEvent||null;
    const IOS=isIos(navigator.userAgent,navigator.platform,navigator.maxTouchPoints);
    function currentInstallMode(){return installMode({hasPrompt:Boolean(installEvent),standalone:isStandalone(window),ios:IOS})}
    function syncInstall(){document.documentElement.dataset.install=currentInstallMode()}
    window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;syncInstall()});
    window.addEventListener('appinstalled',()=>{installEvent=null;syncInstall();notify('RamadhanPro berhasil dipasang')});

    /* Pencarian fitur di header: mengarah ke tampilan yang cocok dengan kata kunci. */
    const SEARCH_MAP=[['home',['beranda','home','dashboard','ringkasan','jadwal','imsak','berbuka','hitung mundur','hidrasi','air']],['calendar',['kalender','tanggal','hijriah','hari ramadhan']],['daily',['mutabaah','harian','shalat','sholat','salat','tilawah','quran','qur','sedekah','puasa','checklist']],['plan',['rencana','doa','zakat','fitrah','infaq','kajian','tarawih','lebaran','kartu','syawal','qadha','safar','iktikaf']],['report',['rapor','laporan','statistik','progres','grafik']],['settings',['akun','pengaturan','tema','lokasi','kota','cadangan','backup','notifikasi','pengingat','privasi','pasang','mode','gelap','terang']]];
    document.addEventListener('submit',event=>{const form=event.target.closest?.('[data-search-form]');if(!form)return;event.preventDefault();const q=String(new FormData(form).get('q')||'').trim().toLowerCase();if(!q)return;const hit=SEARCH_MAP.find(([,words])=>words.some(w=>w.includes(q)||q.includes(w)));if(!hit){notify('Belum ada fitur yang cocok. Coba: shalat, doa, zakat, kalender.');return}view=hit[0];render();window.scrollTo(0,0)});
    syncInstall();
    {const v=new URLSearchParams(location.search).get('view');if(['home','calendar','daily','plan','report','settings'].includes(v))view=v}
    render();
    const startupScreen=document.getElementById('startup-screen'),loginScreen=document.getElementById('login-screen'),profileForm=document.getElementById('profile-form'),profileInput=document.getElementById('profile-name-input');
    function profileIsReady(){try{return localStorage.getItem('ramadhanpro-profile-ready')==='1'}catch{return false}}
    function finishProfile(name=''){db.settings.displayName=name.trim()||'Sahabat';save();try{localStorage.setItem('ramadhanpro-profile-ready','1')}catch{}ensurePersistence();loginScreen.hidden=true;render()}
    window.setTimeout(()=>{startupScreen.classList.add('is-leaving');window.setTimeout(()=>{startupScreen.hidden=true;if(!profileIsReady()){profileInput.value=db.settings.displayName==='Sahabat'?'':db.settings.displayName;loginScreen.hidden=false;profileInput.focus()}},550)},900);
    profileForm.addEventListener('submit',event=>{event.preventDefault();finishProfile(profileInput.value)});
    document.getElementById('profile-skip').addEventListener('click',()=>finishProfile());
